def _postgres_extras() -> None:
    """PostgreSQL-only: PostGIS geometry column + GiST index, full-text GIN index. UNVERIFIED in the dev sandbox
    (no PostgreSQL available there) - run `alembic upgrade head` against the docker-compose database to validate."""
    bind = op.get_bind()
    if bind.dialect.name != "postgresql":
        return
    op.execute("CREATE EXTENSION IF NOT EXISTS postgis")
    op.execute("ALTER TABLE regions ADD COLUMN IF NOT EXISTS geom geometry(Geometry, 4326)")
    op.execute("UPDATE regions SET geom = ST_SetSRID(ST_GeomFromGeoJSON(geometry::text), 4326) WHERE geom IS NULL")
    op.execute("CREATE INDEX IF NOT EXISTS ix_regions_geom ON regions USING GIST (geom)")
    op.execute("CREATE INDEX IF NOT EXISTS ix_chunks_fts ON document_chunks USING GIN (to_tsvector('english', text))")


